class Solution {
    int find(vector<int>& parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
public:
    int swimInWater(vector<vector<int>>& grid) {
        int n = grid.size();
        int N = n * n;
        vector<int> order(N);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                order[grid[i][j]] = i * n + j;

        vector<int> parent(N), rank_(N, 0);
        for (int i = 0; i < N; i++) parent[i] = i;

        vector<bool> active(N, false);
        int target = N - 1;
        int dx[] = {0, 0, 1, -1};
        int dy[] = {1, -1, 0, 0};

        for (int e = 0; e < N; e++) {
            int pos = order[e];
            int r = pos / n, c = pos % n;
            active[pos] = true;
            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    int npos = nr * n + nc;
                    if (active[npos]) {
                        int px = find(parent, pos), py = find(parent, npos);
                        if (px != py) {
                            if (rank_[px] < rank_[py]) swap(px, py);
                            parent[py] = px;
                            if (rank_[px] == rank_[py]) rank_[px]++;
                        }
                    }
                }
            }
            if (active[0] && active[target] && find(parent, 0) == find(parent, target))
                return e;
        }
        return N - 1;
    }
};
